// Package toml decodes TOML v1.0.0 documents using only the standard library.
package toml

import (
	"errors"
	"io"
)

// ErrNotImplemented is returned by Decode until the parser is built.
var ErrNotImplemented = errors.New("toml: decoder not implemented")

// Decode reads a TOML document from r and returns its tagged-value model.
// This foundational stub reads nothing and always reports ErrNotImplemented.
func Decode(r io.Reader) (map[string]any, error) {
	return nil, ErrNotImplemented
}
